1 +package clientmiddleware
2 +
3 +import (
4 +	"context"
5 +
6 +	"github.com/grafana/grafana-plugin-sdk-go/backend"
7 +
8 +	"github.com/grafana/grafana/pkg/infra/log"
9 +	"github.com/grafana/grafana/pkg/plugins"
10 +)
11 +
12 +// NewContextualLoggerMiddleware creates a new plugins.ClientMiddleware that adds
13 +// a contextual logger to the request context.
14 +func NewContextualLoggerMiddleware() plugins.ClientMiddleware {
15 +	return plugins.ClientMiddlewareFunc(func(next plugins.Client) plugins.Client {
16 +		return &ContextualLoggerMiddleware{
17 +			next: next,
18 +		}
19 +	})
20 +}
21 +
22 +type ContextualLoggerMiddleware struct {
23 +	next plugins.Client
24 +}
25 +
26 +// instrumentContext adds a contextual logger with plugin and request details to the given context.
27 +func instrumentContext(ctx context.Context, endpoint string, pCtx backend.PluginContext) context.Context {
28 +	p := []any{"endpoint", endpoint, "pluginId", pCtx.PluginID}
29 +	if pCtx.DataSourceInstanceSettings != nil {
30 +		p = append(p, "dsName", pCtx.DataSourceInstanceSettings.Name)
31 +		p = append(p, "dsUID", pCtx.DataSourceInstanceSettings.UID)
32 +	}
33 +	if pCtx.User != nil {
34 +		p = append(p, "uname", pCtx.User.Login)
35 +	}
36 +	return log.WithContextualAttributes(ctx, p)
37 +}
38 +
39 +func (m *ContextualLoggerMiddleware) QueryData(ctx context.Context, req *backend.QueryDataRequest) (*backend.QueryDataResponse, error) {
40 +	ctx = instrumentContext(ctx, endpointQueryData, req.PluginContext)
41 +	return m.next.QueryData(ctx, req)
42 +}
43 +
44 +func (m *ContextualLoggerMiddleware) CallResource(ctx context.Context, req *backend.CallResourceRequest, sender backend.CallResourceResponseSender) error {
45 +	ctx = instrumentContext(ctx, endpointCallResource, req.PluginContext)
46 +	return m.next.CallResource(ctx, req, sender)
47 +}
48 +
49 +func (m *ContextualLoggerMiddleware) CheckHealth(ctx context.Context, req *backend.CheckHealthRequest) (*backend.CheckHealthResult, error) {
50 +	ctx = instrumentContext(ctx, endpointCheckHealth, req.PluginContext)
51 +	return m.next.CheckHealth(ctx, req)
52 +}
53 +
54 +func (m *ContextualLoggerMiddleware) CollectMetrics(ctx context.Context, req *backend.CollectMetricsRequest) (*backend.CollectMetricsResult, error) {
55 +	ctx = instrumentContext(ctx, endpointCollectMetrics, req.PluginContext)
56 +	return m.next.CollectMetrics(ctx, req)
57 +}
58 +
59 +func (m *ContextualLoggerMiddleware) SubscribeStream(ctx context.Context, req *backend.SubscribeStreamRequest) (*backend.SubscribeStreamResponse, error) {
60 +	return m.next.SubscribeStream(ctx, req)
61 +}
62 +
63 +func (m *ContextualLoggerMiddleware) PublishStream(ctx context.Context, req *backend.PublishStreamRequest) (*backend.PublishStreamResponse, error) {
64 +	return m.next.PublishStream(ctx, req)
65 +}
66 +
67 +func (m *ContextualLoggerMiddleware) RunStream(ctx context.Context, req *backend.RunStreamRequest, sender *backend.StreamSender) error {
68 +	return m.next.RunStream(ctx, req, sender)
69 +}"},{"filename":"pkg/plugins/log/ifaces.go","patchWithLinesStr":"## file: 'pkg/plugins/log/ifaces.go'

